record.field:
today = datetime.date.today()
records = env['x_control_de_desecho'].search([
    ('x_studio_active', '=', True),
])
for record in records:
    product = record.x_studio_product_product
    locations = record.x_studio_warehouse
    if not product or not locations:
        continue
    errors = []  # acumular errores para postear UN solo mensaje al final
    quant_data = env['stock.quant'].read_group(
        [
            ('product_id', '=', product.id),
            ('location_id', 'in', locations.ids),
            ('quantity', '<', 0)
        ],
        ['quantity:sum'],
        ['location_id']
    )
    for quant in quant_data:
        location_id = quant['location_id'][0]
        total_qty = quant['quantity']
        if total_qty >= 0:
            continue
        abs_qty = abs(total_qty)
        if abs_qty <= 0.20:
            qty_to_produce = abs_qty
        else:
            int_part = int(abs_qty)
            qty_to_produce = int_part if abs_qty == int_part else int_part + 1
        # Buscar picking type por ubicación de origen
        picking_type = env['stock.picking.type'].search([
            ('code', '=', 'mrp_operation'),
            ('default_location_src_id', '=', location_id),
        ], limit=1)
        # Si no encuentra por src, buscar por dest
        if not picking_type:
            picking_type = env['stock.picking.type'].search([
                ('code', '=', 'mrp_operation'),
                ('default_location_dest_id', '=', location_id),
            ], limit=1)
        mo_vals = {
            'product_id': product.id,
            'product_qty': qty_to_produce,
            'product_uom_id': product.uom_id.id,
            'location_src_id': location_id,
            'location_dest_id': location_id,
            'company_id': record.x_studio_company.id,
            'origin': f"AUTO FIX NEGATIVE {record.display_name}",
        }
        if picking_type:
            mo_vals['picking_type_id'] = picking_type.id
        try:
            mo = env['mrp.production'].create(mo_vals)
            # (sin message_post de éxito — antes era el que llenaba el chatter)
        except Exception as e:
            errors.append((location_id, str(e)))
    # UN solo mensaje al chatter, solo si hubo errores
    if errors:
        lines = "".join(
            f"<li>Ubicación #{loc_id}: {msg}</li>"
            for loc_id, msg in errors
        )
        record.message_post(
            body=f"🚨 ERROR creando MO {product.display_name}:<ul>{lines}</ul>"
        )
